files.content:
[hidden] { display: none !important; }

:root {
  --bg: #1e1e2f;
  --card-bg: #2b2b3d;
  --text: #e8e8f0;
  --accent: #6c63ff;
  --accent-hover: #5a52e0;
  --accent-pressed: #4a43c0;
  --focus: #ffd166;
  --border: #3d3d55;
}

* {
  box-sizing: border-box;
}

body {
  margin: 0;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--bg);
  color: var(--text);
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 16px;
  padding: 16px;
}

.card {
  background: var(--card-bg);
  border-radius: 16px;
  padding: 24px;
  width: 100%;
  max-width: 420px;
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.4);
  display: flex;
  flex-direction: column;
  gap: 20px;
}

h1 {
  margin: 0;
  font-size: 1.5rem;
  text-align: center;
  letter-spacing: 0.5px;
}

.swatch {
  width: 100%;
  height: 120px;
  border-radius: 12px;
  border: 2px solid var(--border);
  background: #000;
  transition: background 0.15s ease;
}

.hex {
  margin: 0;
  text-align: center;
  font-size: 1.25rem;
  font-family: ui-monospace, 'SF Mono', Menlo, Consolas, monospace;
  letter-spacing: 1px;
}

.controls {
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.control {
  display: grid;
  grid-template-columns: 60px 1fr 48px;
  align-items: center;
  gap: 12px;
}

label {
  font-weight: 600;
}

input[type="range"] {
  -webkit-appearance: none;
  appearance: none;
  width: 100%;
  height: 8px;
  border-radius: 4px;
  background: var(--border);
  outline: none;
  cursor: pointer;
}

input[type="range"]::-webkit-slider-thumb {
  -webkit-appearance: none;
  appearance: none;
  width: 22px;
  height: 22px;
  border-radius: 50%;
  background: var(--accent);
  border: 2px solid var(--text);
  cursor: pointer;
  transition: background 0.15s, transform 0.1s;
}

input[type="range"]::-moz-range-thumb {
  width: 22px;
  height: 22px;
  border-radius: 50%;
  background: var(--accent);
  border: 2px solid var(--text);
  cursor: pointer;
  transition: background 0.15s, transform 0.1s;
}

input[type="range"]:hover::-webkit-slider-thumb {
  background: var(--accent-hover);
}

input[type="range"]:hover::-moz-range-thumb {
  background: var(--accent-hover);
}

input[type="range"]:active::-webkit-slider-thumb {
  background: var(--accent-pressed);
  transform: scale(1.1);
}

input[type="range"]:active::-moz-range-thumb {
  background: var(--accent-pressed);
  transform: scale(1.1);
}

input[type="range"]:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 4px;
}

output {
  text-align: right;
  font-variant-numeric: tabular-nums;
  font-family: ui-monospace, 'SF Mono', Menlo, Consolas, monospace;
}

button {
  font: inherit;
  font-weight: 600;
  padding: 12px 20px;
  border: none;
  border-radius: 10px;
  background: var(--accent);
  color: #fff;
  cursor: pointer;
  transition: background 0.15s, transform 0.1s;
}

button:hover {
  background: var(--accent-hover);
}

button:active {
  background: var(--accent-pressed);
  transform: scale(0.98);
}

button:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 3px;
}

@media (max-width: 400px) {
  .control {
    grid-template-columns: 50px 1fr 40px;
    gap: 8px;
  }
  .card {
    padding: 16px;
  }
}

const red = document.getElementById('red');
const green = document.getElementById('green');
const blue = document.getElementById('blue');
const redValue = document.getElementById('redValue');
const greenValue = document.getElementById('greenValue');
const blueValue = document.getElementById('blueValue');
const swatch = document.getElementById('swatch');
const hex = document.getElementById('hex');
const randomBtn = document.getElementById('randomBtn');

function toHex(n) {
  return n.toString(16).padStart(2, '0');
}

function update() {
  const r = Number(red.value);
  const g = Number(green.value);
  const b = Number(blue.value);
  const color = `rgb(${r}, ${g}, ${b})`;
  swatch.style.background = color;
  hex.textContent = `#${toHex(r)}${toHex(g)}${toHex(b)}`;
  redValue.textContent = r;
  greenValue.textContent = g;
  blueValue.textContent = b;
}

function randomize() {
  red.value = Math.floor(Math.random() * 256);
  green.value = Math.floor(Math.random() * 256);
  blue.value = Math.floor(Math.random() * 256);
  update();
}

[red, green, blue].forEach((slider) => {
  slider.addEventListener('input', update);
});

randomBtn.addEventListener('click', randomize);

update();
